{
  "requirements": [
    {
      "id": "F-01",
      "text": "The ATM system shall ensure all transactions comply with applicable financial regulations and standards.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The ATM system shall provide detailed transaction logs including date, time, type, amount, and updated balance.",
      "quality_axes": ["Responsibility|Trustworthiness"],
      "derived_from": ["RES-02", "TRU-03"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-03",
      "text": "The ATM system shall prevent users from executing transactions that would create negative account balances.",
      "quality_axes": ["Safety|Trustworthiness|Responsibility"],
      "derived_from": ["RES-03", "TRU-04"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-04",
      "text": "The application shall validate user identity through a secure PIN entry mechanism.",
      "quality_axes": ["Safety|Trustworthiness|Responsibility"],
      "derived_from": ["RES-04", "TRU-02"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-05",
      "text": "The system shall automatically withdraw funds from a related savings account only when sufficient funds are available.",
      "quality_axes": ["Safety|Efficiency|Trustworthiness"],
      "derived_from": ["RES-05", "SAF-02"],
      "kaos_level": "operational",
      "parent": "F-03"
    },
    {
      "id": "F-06",
      "text": "The application shall notify users immediately if a transaction cannot be completed due to insufficient funds.",
      "quality_axes": ["Safety|Trustworthiness"],
      "derived_from": ["RES-06", "SAF-03"],
      "kaos_level": "operational",
      "parent": "F-03"
    },
    {
      "id": "F-07",
      "text": "The system shall ensure that all transactions are encrypted during transmission.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-01"],
      "kaos_level": "tactical",
      "parent": "F-01"
    },
    {
      "id": "F-08",
      "text": "The ATM system shall log all transactions with date, time, type, amount, and resulting balance.",
      "quality_axes": ["Safety|Trustworthiness"],
      "derived_from": ["SAF-04"],
      "kaos_level": "operational",
      "parent": "F-01"
    },
    {
      "id": "F-09",
      "text": "The ATM system shall automatically shut down during periods of inactivity to save energy.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-06"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-10",
      "text": "The ATM system shall only process transactions within 3 seconds to ensure user responsiveness.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-11",
      "text": "The ATM system shall provide an option for clients to receive electronic transaction records instead of paper receipts.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-12",
      "text": "The ATM system shall assess the environmental impact of its operations annually and report findings to stakeholders.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-07"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-13",
      "text": "The ATM system shall provide a mechanism for users to review their transaction history securely.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-14",
      "text": "The ATM system shall ensure that no account can have a negative balance.",
      "quality_axes": ["Safety|Trustworthiness"],
      "derived_from": ["SAF-01", "EFF-04"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-15",
      "text": "The system shall implement load balancing to manage transaction requests effectively.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-07"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-16",
      "text": "The ATM system shall ensure that all recorded transactions are logged in a way that minimizes data storage requirements.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-04"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-17",
      "text": "The ATM application shall optimize data retrieval to minimize latency when accessing transaction history.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-03"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-18",
      "text": "The ATM system shall minimize energy consumption by optimizing transaction processing to reduce idle states.",
      "quality_axes": ["Sustainability|Efficiency"],
      "derived_from": ["GRN-01"],
      "kaos_level": "tactical",
      "parent": null
    },
      {
      "id": "F-19",
      "text": "The ATM system shall maintain user privacy by securely encrypting all personal and financial data.",
      "quality_axes": ["Trustworthiness|Responsibility"],
      "derived_from": ["RES-07"],
      "kaos_level": "tactical",
      "parent": null
    }
  ],
